// One call stack; callbacks wait in queues until the stack is empty.
const log = [];
const say = (s) => { log.push(s); console.log(s); };

say('1 sync: script start');
setTimeout(() => say('5 task: setTimeout 0'), 0);      // goes to the task queue
Promise.resolve().then(() => say('3 microtask: promise then'));
queueMicrotask(() => say('4 microtask: queueMicrotask'));
say('2 sync: script end');

// The loop only starts taking callbacks after the script (one task) ends:
// all sync lines, then ALL microtasks, then the next task (the timer).
// Time O(callbacks), space O(queued callbacks).

// Microtasks drain completely (even new ones) before the next task runs.
console.log('start');
setTimeout(() => console.log('task: timeout A'), 0);
setTimeout(() => console.log('task: timeout B'), 0);

Promise.resolve().then(() => {
  console.log('microtask 1');
  // queued DURING the drain: still runs before timeout A
  queueMicrotask(() => console.log('microtask 3 (queued by microtask 1)'));
});
queueMicrotask(() => console.log('microtask 2'));

// Each timer is its own task; microtasks run after each task.
