// A tiny async/await driver built from a generator.
function run(genFn) {
  return new Promise((resolve, reject) => {
    const it = genFn();
    function step(method, arg) {
      let r;
      try { r = it[method](arg); }          // resume the paused function
      catch (e) { return reject(e); }       // body threw -> reject
      if (r.done) return resolve(r.value);  // return v -> resolve
      // "await": wrap the yielded value, resume in a microtask later
      Promise.resolve(r.value).then(
        (v) => step('next', v),
        (e) => step('throw', e));           // rejection throws at the yield
    }
    step('next');
  });
}

const delay = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));

run(function* () {
  console.log('before');
  const a = yield delay(10, 20);
  let b;
  try { yield Promise.reject(new Error('boom')); }
  catch (e) { b = e.message; }              // try/catch works across yield
  return a + ' ' + b;
}).then((v) => console.log('result:', v));
