// Where do setTimeout 0, then() and queueMicrotask run?
const order = [];
setTimeout(() => order.push('setTimeout 0 (task)'), 0);
Promise.resolve().then(() => order.push('promise.then (microtask)'));
queueMicrotask(() => order.push('queueMicrotask (microtask)'));
order.push('sync code');

// Exceptions differ: then() turns a throw into a rejected promise,
// queueMicrotask lets it surface as an uncaught error.
const p = Promise.resolve().then(() => { throw new Error('in then'); });
p.catch((e) => order.push('caught from then: ' + e.message));

setTimeout(() => {
  console.log(order.join('\n'));
}, 5);

// try/catch only covers the current call stack.
try {
  setTimeout(() => { throw new Error('late'); }, 0);
  console.log('try block finished');
} catch (e) {
  console.log('never printed');
}

// Fix 1: catch inside the callback.
setTimeout(() => {
  try { throw new Error('inside callback'); }
  catch (e) { console.log('caught:', e.message); }
}, 0);

// Fix 2: wrap in a promise so errors become rejections.
const later = (ms) => new Promise((res, rej) =>
  setTimeout(() => rej(new Error('promisified')), ms));
(async () => {
  try { await later(5); }
  catch (e) { console.log('caught with await:', e.message); }
})();

// The first timer's error would crash Node, so we report it instead.
process.on('uncaughtException', (e) => console.log('global handler:', e.message));

// return vs return await inside try/catch/finally.
const fail = () => new Promise((_, rej) => setTimeout(() => rej(new Error('bad')), 5));

async function noAwait() {
  try { return fail(); }            // leaves try immediately
  catch (e) { return 'local catch'; }
  finally { console.log('noAwait finally (runs too early)'); }
}
async function withAwait() {
  try { return await fail(); }      // waits inside try
  catch (e) { return 'local catch'; }
  finally { console.log('withAwait finally (after settle)'); }
}

(async () => {
  try { console.log('noAwait ->', await noAwait()); }
  catch (e) { console.log('noAwait ->', 'caller got', e.message); }
  console.log('withAwait ->', await withAwait());
})();

