// Fix: process in slices and yield to the task queue between them.
let done = 0;
function chunked() {
  const end = done + 25000;
  while (done < end) done++;                 // one slice of work
  if (done < 100000) setTimeout(chunked, 0); // yield: other tasks may run
  else console.log('chunked work finished:', done);
}
chunked();

// What await fetch() does, with a fake fetch so it runs offline.
function fakeFetch(url) {
  console.log('  fetch called, request started:', url);
  return new Promise((resolve) => setTimeout(() => resolve({
    ok: url.endsWith('missing'),   // pretend the second URL gives 404
    status: url.endsWith('missing') ? 404 : 200,
    json: async () => ({ url }),
  }), 10));
}
// swap: ok true when status 200
const f = async (u) => { const r = await fakeFetch(u); r.ok = r.status === 200; return r; };

async function load(url) {
  console.log('1 before await');
  const res = await f(url);            // function suspends, stack unwinds
  console.log('3 resumed, status', res.status);
  if (!res.ok) return 'HTTP error ' + res.status;   // 404 does NOT reject
  return (await res.json()).url;
}
load('/data').then((r) => console.log('4 result:', r))
  .then(() => load('/missing')).then((r) => console.log('4 result:', r));
