// Virtual clock model: rAF callbacks run only at a frame boundary (every 16 ms).
let now = 0;
const tasks = [];           // {time, name}
const rafQueue = [];
const log = [];

function setTimeout0(name, at) { tasks.push({ time: at, name }); }
function raf(name) { rafQueue.push(name); }

function simulate(label, timeoutAt, taskStart) {
  tasks.length = 0; rafQueue.length = 0; log.length = 0;
  now = taskStart;                  // the current task ends at this time
  raf('rAF');
  setTimeout0('timeout 0', timeoutAt);
  // loop: run due timers, and at each 16 ms boundary run rAF before painting
  while (tasks.length || rafQueue.length) {
    const nextFrame = Math.ceil((now + 0.001) / 16) * 16;
    const t = tasks.length ? tasks[0].time : Infinity;
    if (t <= nextFrame && tasks.length) { now = t; log.push(tasks.shift().name); }
    else { now = nextFrame; while (rafQueue.length) log.push(rafQueue.shift()); }
  }
  console.log(label + ': ' + log.join(' -> '));
}
simulate('task ends at 2ms, timer at 3ms', 3, 2);
simulate('task ends at 15ms, timer at 17ms', 17, 15);

// Concurrency-limited runner: workers share an index; next++ is atomic.
function runLimited(tasks, limit) {
  const results = new Array(tasks.length);
  let next = 0, running = 0, maxRunning = 0;
  const worker = async () => {
    while (next < tasks.length) {
      const i = next++;                 // no lock needed: run-to-completion
      running++; maxRunning = Math.max(maxRunning, running);
      results[i] = await tasks[i]();    // write at index keeps input order
      running--;
    }
  };
  const workers = Array.from({ length: limit }, worker);
  return Promise.all(workers).then(() => ({ results, maxRunning }));
}

const delay = (ms, v) => () => new Promise((r) => setTimeout(() => r(v), ms));
