// Count ticks: modern await on a native promise vs the pre-2019 algorithm.
async function modern(log) {
  await Promise.resolve();            // 1 tick (PromiseResolve reuses it)
  log('modern await resumed');
}
async function legacy(log) {
  // old behaviour: wrap in a new promise first (about 3 ticks)
  await new Promise((resolve) => resolve(Promise.resolve()));
  log('legacy-style await resumed');
}

